function computePerkSynergies(perks) {
  const counts = { attack: 0, defense: 0, control: 0 };
  for (const p of perks) {
    const cat = p.category || "control";
    counts[cat]++;
  }
  const synergies = [];
  const penalties = [];
  let shootingDelta = 0;
  let passingDelta = 0;
  let defendingDelta = 0;
  let paceDelta = 0;
  let staminaDelta = 0;
  let goalkeepingDelta = 0;
  let dribblingDelta = 0;
  let composureDelta = 0;
  let positioningDelta = 0;
  if (counts.attack >= 2) {
    synergies.push("\u950B\u8292\u6BD5\u9732 (2+\u8FDB\u653B\u8BCD\u6761): \u5C04\u95E8+4 \u901F\u5EA6+4");
    shootingDelta += 4;
    paceDelta += 4;
    if (counts.attack >= 3) {
      synergies.push("\u4E07\u7BAD\u9F50\u53D1 (3+\u8FDB\u653B\u6781\u81F4): \u5C04\u95E8\u989D\u5916+4 \u51B7\u9759+3");
      shootingDelta += 4;
      composureDelta += 3;
    }
    if (counts.defense === 0) {
      penalties.push("\u653B\u5F3A\u5B88\u5F31\u53CD\u566C: \u5168\u961F\u9632\u5B88 -4");
      defendingDelta -= 4;
    }
  }
  if (counts.defense >= 2) {
    synergies.push("\u94DC\u5899\u94C1\u58C1 (2+\u9632\u5B88\u8BCD\u6761): \u9632\u5B88+4 \u6251\u6551+4");
    defendingDelta += 4;
    goalkeepingDelta += 4;
    if (counts.defense >= 3) {
      synergies.push("\u7EDD\u5BF9\u96F6\u5C01 (3+\u9632\u5B88\u6781\u81F4): \u9632\u5B88\u989D\u5916+4 \u7AD9\u4F4D+4");
      defendingDelta += 4;
      positioningDelta += 4;
    }
    if (counts.attack === 0) {
      penalties.push("\u4FDD\u5B88\u53CD\u566C: \u5168\u961F\u5C04\u95E8 -4");
      shootingDelta -= 4;
    }
  }
  if (counts.control >= 2) {
    synergies.push("\u4E2D\u573A\u7EDF\u6CBB (2+\u63A7\u5236\u8BCD\u6761): \u4F20\u7403+5");
    passingDelta += 5;
    if (counts.control >= 3) {
      synergies.push("\u5168\u80FD\u5927\u5E08 (3+\u63A7\u5236\u6781\u81F4): \u4F20\u7403\u989D\u5916+4 \u76D8\u5E26+4");
      passingDelta += 4;
      dribblingDelta += 4;
    }
    if (counts.defense === 0) {
      penalties.push("\u9AD8\u4F4D\u63A7\u7403\u6D88\u8017\u53CD\u566C: \u5168\u961F\u4F53\u80FD -3");
      staminaDelta -= 3;
    }
  }
  if (counts.attack >= 1 && counts.defense >= 1 && counts.control >= 1) {
    synergies.push("\u4E09\u624D\u5F52\u5143 (\u653B/\u9632/\u63A7\u5747\u8861): \u4F20\u5C04\u9632\u51B7 +3");
    passingDelta += 3;
    shootingDelta += 3;
    defendingDelta += 3;
    composureDelta += 3;
  }
  return {
    counts,
    synergies,
    penalties,
    shootingDelta,
    passingDelta,
    defendingDelta,
    paceDelta,
    staminaDelta,
    goalkeepingDelta,
    dribblingDelta,
    composureDelta,
    positioningDelta
  };
}
