function ptAt(angleDeg, radius) {
  const rad = angleDeg * Math.PI / 180;
  return {
    nx: Math.round((0.5 + Math.cos(rad) * radius) * 1e3) / 1e3,
    ny: Math.round((0.5 + Math.sin(rad) * radius) * 1e3) / 1e3
  };
}
function lerpPt(a, b, t) {
  return {
    nx: Math.round((a.nx + (b.nx - a.nx) * t) * 1e3) / 1e3,
    ny: Math.round((a.ny + (b.ny - a.ny) * t) * 1e3) / 1e3
  };
}
