function makeProfile(instantAction, instantLabel, vfxTheme, linkedElement, aName, aTag, bName, bTag) {
  return {
    instantAction,
    instantLabel,
    vfxTheme,
    linkedElement,
    mutations: [
      { choice: "A", name: aName, tag: aTag, shortDesc: MUTATION_TAG_DESC[aTag] },
      { choice: "B", name: bName, tag: bTag, shortDesc: MUTATION_TAG_DESC[bTag] }
    ]
  };
}
