      (c) => `\u5BF9\u624B\u9632\u5B88\u4E60\u60EF\u9C81\u83BD\u4E0B\u811A\uFF0C\u591A\u7528\u7A81\u7834\u4E0E\u53D8\u5411\u51B2\u51FB\u80FD\u5236\u9020\u5927\u91CF\u524D\u573A\u4EFB\u610F\u7403\u751A\u81F3\u7EA2\u9EC4\u724C`,
      (c) => `\u9762\u5BF9${c.opp.name}\u7684\u7C97\u91CE\u9632\u5B88\uFF0C\u5927\u80C6\u4E00\u5BF9\u4E00\u5F3A\u7A81\u80FD\u8FC5\u901F\u8BA9\u5BF9\u624B\u4E3B\u529B\u80CC\u4E0A\u9EC4\u724C\u675F\u624B\u675F\u811A`,
      (c) => `\u5BF9\u624B\u72AF\u89C4\u6570\u5C45\u9AD8\u4E0D\u4E0B\uFF0C\u5229\u7528\u524D\u573A\u5B9A\u4F4D\u7403\u548C\u70B9\u7403\u538B\u529B\u80FD\u8F7B\u677E\u6253\u7834\u6BD4\u8D5B\u5E73\u8861`,
      (c) => `\u540E\u536B${c.cbName}\u62E6\u622A\u52A8\u4F5C\u8FC7\u5927\uFF0C\u6B63\u9762\u5E26\u7403\u52A0\u901F\u53D8\u5411\u6781\u6613\u9A97\u51FA\u72AF\u89C4\u826F\u673A`
