      (c) => `\u4E0E\u5176\u548C${c.cbName}\u62FC\u9AD8\u7A7A\u5BF9\u6297\uFF0C\u4E0D\u5982\u591A\u6253\u5730\u9762\u811A\u4E0B\u914D\u5408\u4E0E\u659C\u5411\u7A7F\u63D2`,
      (c) => `\u5BF9\u624B\u4E2D\u536B\u4E60\u60EF\u4E0A\u62A2\u5374\u56DE\u8EAB\u6162\uFF0C\u5047\u52A8\u4F5C\u6643\u52A8\u4E0E\u6A2A\u5411\u62C9\u626F\u80FD\u8BA9\u5176\u9891\u9891\u5931\u4F4D`,
      (c) => `${c.cbName}\u5728\u5F00\u653E\u7A7A\u95F4\u5185\u4E00\u5BF9\u4E00\u9632\u5B88\u5403\u4E8F\uFF0C\u628A\u9635\u578B\u62C9\u5F00\u6253\u5FEB\u8282\u594F\u53CD\u51FB\u6548\u679C\u62D4\u7FA4`
