  const recentFormText = oppRecent.length === 0 ? "\u8D5B\u5B63\u521D\u8F6E\uFF0C\u6682\u65E0\u8FD1\u671F\u8054\u8D5B\u6837\u672C" : fam >= 35 ? `\u8FD1${oppRecent.length}\u8F6E [${formChars.join("-")}] (${scoreDetails.join(" / ")}) \xB7 \u8FDB${gf}\u5931${ga}` : `\u8FD1${oppRecent.length}\u8F6E\u8D70\u52BF [${formChars.join("-")}] (\u6DF1\u5EA6\u4FA6\u5BDF\u89E3\u9501\u6BD4\u5206\u8BE6\u60C5)`;
  const h2hText = rec.playedCount === 0 ? "\u9996\u6B21\u4EA4\u950B \xB7 \u6682\u65E0\u8FC7\u5F80\u6218\u7EE9" : `\u5386\u53F2\u4EA4\u950B ${rec.playedCount}\u573A (${rec.wins}\u80DC${rec.draws}\u5E73${rec.losses}\u8D1F${rec.lastScore ? ` \xB7 \u4E0A\u6B21 ${rec.lastScore}` : ""})`;
